      { k: 'pick', age: 11, q: 'Which one fits?', s: 'The ___ race starts at noon.', opts: ['women\'s', 'womens\'', 'womens'], ans: 'women\'s', why: 'Women already means more than one, so we add an apostrophe and s: women\'s.' },
      { k: 'pick', age: 11, q: 'Which one fits?', s: 'Chen and Zara share a room. The ___ room is blue.', opts: ['kids\'', 'kid\'s', 'kids'], ans: 'kids\'', why: 'The room belongs to two kids, so the apostrophe goes after the s: kids\'.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'Because the trail was muddy, we wore our boots.', mark: ',', why: 'The opening part of the sentence ends at "muddy", so a comma goes there before the main part.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'Of course, you can borrow my pen.', mark: ',', why: 'Of course starts the sentence, so a comma comes right after it.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'Ravi, after you finish your snack, please wash your hands.', mark: ',', nth: 1, why: 'The opening part of the sentence ends at "snack", so a comma goes there before the main part.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'We need tickets, snacks, maps, and a camera for the trip.', mark: ',', nth: 1, why: 'Commas keep the things in a list apart, so a comma goes after "snacks".' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'If you finish early, you may read quietly.', mark: ',', why: 'The opening part of the sentence ends at "early", so a comma goes there before the main part.' },
      { k: 'place', age: 12, q: 'Tap where the period goes.', full: 'The library was quiet. Everyone was reading.', mark: '.', nth: 0, why: 'The first sentence stops after "quiet". The next sentence starts with a capital letter.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'Yes, Aisha, the answer is seven.', mark: ',', nth: 0, why: 'When yes or no starts a sentence, a comma comes right after it.' },
      { k: 'place', age: 12, q: 'Tap where the question mark goes.', full: 'Did you know that some frogs can glide?', mark: '?', why: 'This sentence is asking something, so a question mark goes at the end.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'Once the paint dried, we hung the picture on the wall.', mark: ',', why: 'The opening part of the sentence ends at "dried", so a comma goes there before the main part.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'Sorry, Diego, I did not hear you.', mark: ',', nth: 1, why: 'We are talking to someone by name, so a comma keeps the name apart from the rest.' },
      { k: 'place', age: 12, q: 'Tap where the exclamation mark goes.', full: 'I cannot believe we finished the whole puzzle!', mark: '!', why: 'This sentence shows a big feeling, so it ends with an exclamation mark.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'After a long, slow climb, we reached the top.', mark: ',', nth: 1, why: 'The opening part of the sentence ends at "climb", so a comma goes there before the main part.' },
      { k: 'place', age: 12, q: 'Tap where the comma goes.', full: 'To make the cake, we mixed flour and sugar.', mark: ',', why: 'The opening part of the sentence ends at "cake", so a comma goes there before the main part.' },
      { k: 'meaning', age: 12, pic: 'pause', q: 'Which one says Yuki is the coach?', opts: ['Yuki, the coach wants you.', 'Yuki, the coach, wants you.'], ans: 'Yuki, the coach, wants you.', why: 'Commas around \'the coach\' tell us who Yuki is. One comma after Yuki means you are giving Yuki a message.' },
      { k: 'meaning', age: 12, pic: 'pause', q: 'Which one says Ben is the one talking?', opts: ['Zara, said Ben, can sing.', 'Zara said Ben can sing.'], ans: 'Zara, said Ben, can sing.', why: 'The commas around \'said Ben\' show Ben is speaking, and Zara is the one who can sing.' },
      { k: 'meaning', age: 12, pic: 'pause', q: 'Which one says Kofi is the baker?', opts: ['Kofi, the baker is here.', 'Kofi, the baker, is here.'], ans: 'Kofi, the baker, is here.', why: 'Commas around \'the baker\' tell us who Kofi is. One comma after Kofi means you are talking to Kofi.' },
      { k: 'meaning', age: 12, pic: 'own', q: 'Which one is about a room for many teachers?', opts: ['The teachers\' room is upstairs.', 'The teacher\'s room is upstairs.'], ans: 'The teachers\' room is upstairs.', why: 'Teachers\' with the apostrophe after the s means the room belongs to many teachers.' },
      { k: 'meaning', age: 12, pic: 'says', q: 'Which one shows Ella is the one speaking?', opts: ['Ella said, "Diego is tall."', '"Ella," said Diego, "is tall."'], ans: 'Ella said, "Diego is tall."', why: 'In the first one, Ella speaks the words in quotation marks. In the second, Diego is speaking about Ella.' },
      { k: 'meaning', age: 12, pic: 'says', q: 'Which one says Zara has a kite?', opts: ['"Zara," said Priya, "has a kite."', 'Zara said Priya has a kite.'], ans: '"Zara," said Priya, "has a kite."', why: 'The quotation marks show Priya is speaking, and the words say Zara has a kite.' },
      { k: 'meaning', age: 12, pic: 'talkto', q: 'Which one is talking TO Ben?', opts: ['Do you want to call, Ben?', 'Do you want to call Ben?'], ans: 'Do you want to call, Ben?', why: 'With the comma, you are asking Ben. Without it, you are asking if someone wants to phone Ben.' },
      { k: 'meaning', age: 12, pic: 'ask', q: 'Which one is asking?', opts: ['You finished the whole book?', 'You finished the whole book.'], ans: 'You finished the whole book?', why: 'The question mark turns the words into a surprised question.' },
      { k: 'meaning', age: 12, pic: 'tell', q: 'Which one ends the right way?', opts: ['Ask Zara where the glue is.', 'Ask Zara where the glue is?'], ans: 'Ask Zara where the glue is.', why: 'This tells someone to ask Zara. You are not asking a question yourself, so it ends with a period.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: '"The bus is late___ said Diego.', opts: [',"', '."', '?"'], ans: ',"', why: 'When said comes after a telling quote, a comma goes inside the closing quotation marks, not a period.' },
      { k: 'pick', age: 12, q: 'Which mark goes at the end?', s: 'Tell me where the map is___', opts: ['.', '?'], ans: '.', why: 'This tells someone what to do. It is not a question, so it ends with a period.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: 'We ___ left sooner.', opts: ['could\'ve', 'could of', 'couldve'], ans: 'could\'ve', why: 'Could\'ve is short for could have. It sounds like could of, but of is never right here.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: '"Watch out___ called Ravi.', opts: ['!"', '"!', '?"'], ans: '!"', why: 'The exclamation mark belongs to what Ravi called out, so it goes inside the quotation marks.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: 'The ___ coats were wet from the rain.', opts: ['people\'s', 'peoples\'', 'peoples'], ans: 'people\'s', why: 'People already means more than one, so we add an apostrophe and s: people\'s.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: '___ been a long day.', opts: ['It\'s', 'Its', 'It\'is'], ans: 'It\'s', why: 'Here it\'s is short for it has: it has been a long day.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: 'Mom asked, ___', opts: ['"Who wants soup?"', '"Who wants soup"?', 'Who wants soup?"'], ans: '"Who wants soup?"', why: 'Quotation marks go around Mom\'s whole question, with the question mark inside.' },
      { k: 'pick', age: 12, q: 'Which one fits?', s: 'Both dogs ran to the door. The ___ tails were wagging.', opts: ['dogs\'', 'dog\'s', 'dogs'], ans: 'dogs\'', why: 'The tails belong to both dogs, so the apostrophe goes after the s: dogs\'.' }
